# --------------------------------------------------------------------------- #
# Fakta o behu - pocitana, ne psana modelem
# --------------------------------------------------------------------------- #
def _parse_ts(s: str | None):
    try:
        return datetime.fromisoformat(str(s).replace("Z", "+00:00"))
    except (ValueError, TypeError):
        return None


def run_duration(run_summary: dict) -> str | None:
    """Jak dlouho beh trval. Z casu prvniho a posledniho kola."""
    rounds = run_summary.get("rounds") or []
    if not rounds:
        return None
    start = _parse_ts(rounds[0].get("started"))
    end = _parse_ts(rounds[-1].get("ended")) or _parse_ts(run_summary.get("finished_at"))
    if not (start and end) or end < start:
        return None
    mins = int((end - start).total_seconds() // 60)
    if mins < 1:
        return "pod minutu"
    if mins < 60:
        return f"{mins} min"
    return f"{mins // 60} h {mins % 60} min"


def course_sentence(run_summary: dict) -> str:
    """Jednou vetou, jak beh probihal - z poctu vytek po kolech."""
    rounds = [r for r in (run_summary.get("rounds") or []) if r.get("status") != "WORKER_FAIL"]
    if not rounds:
        return "Běh se nerozjel."
    counts = [len(r.get("required_changes") or []) for r in rounds]
    total = len(rounds)
    if total == 1:
        return "Prošlo napoprvé, verifier neměl co vytknout."
    stalled = len(counts) >= 3 and counts[-1] >= min(counts[:-1])
    trend = "ale výtek neubývalo" if stalled else "výtek postupně ubývalo"
    return f"Verifier vracel výstup {total - 1}× k opravě, {trend}."


def _clip(text: str, cap: int = CAP_SENTENCE) -> str:
    text = " ".join(str(text).split())
    return text if len(text) <= cap else text[: cap - 1].rsplit(" ", 1)[0] + "…"


def _bullets(items, cap: int, css: str = "") -> str:
    items = [i for i in (items or []) if str(i).strip()]
    shown = [f"<li>{_html.escape(_clip(i))}</li>" for i in items[:cap]]
    if not shown:
        return ""
    extra = ""
    if len(items) > cap:
        extra = f'<p class="more">a dalších {len(items) - cap} v technickém detailu</p>'
    cls = f' class="{css}"' if css else ""
    return f"<ul{cls}>{''.join(shown)}</ul>{extra}"


def _tile(key: str, value: str, state: str = "") -> str:
    cls = f"tile state-{state}" if state else "tile"
    return (f'<div class="{cls}"><span class="k">{_html.escape(key)}</span>'
            f'<span class="v">{_html.escape(value)}</span></div>')


def _block(title: str, inner: str, css: str = "block") -> str:
    if not inner:
        return ""
    return f'<section class="{css}"><h2>{_html.escape(title)}</h2>{inner}</section>'


# --------------------------------------------------------------------------- #
# Souhrn - jedna A4
# --------------------------------------------------------------------------- #
def assignment_lines(spec_text: str, cap: int = 4) -> list[str]:
    """Zadani vytazene z task-spec.md - co po agentovi chtel Master.

    Deterministicky: nadpis prvni sekce ignorujeme, bereme prvni odstavce a odrazky
    az po blok s realnymi daty (ten uz je technicky a do souhrnu nepatri)."""
    out = []
    for raw in (spec_text or "").splitlines():
        line = raw.strip()
        if not line:
            continue
        if line.startswith("=====") or line.lower().startswith("## rozsah"):
            break
        if line.startswith("#"):
            continue
        line = re.sub(r"^[-*]\s+", "", line)
        line = re.sub(r"\*\*(.+?)\*\*", r"\1", line)
        if line.startswith("/") or line.startswith("`/"):   # cesty do souhrnu nepatri
            continue
        out.append(line)
        if len(out) >= cap:
            break
    return out


