def _doc_title(path: str) -> str:
    """Nazev dokumentu z jeho frontmatter, jinak nazev souboru bez pripony."""
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            for line in f.read(1200).splitlines()[:12]:
                if line.startswith("title:"):
                    return line.split(":", 1)[1].strip().strip("\"'")
    except OSError:
        pass
    return Path(path).stem.replace("-", " ")


